package com.trombokendu.chronos.domain; import java.time.*;import java.util.*; public record RecurringRuleDefined(UUID eventId,Instant at,Category category,Money amount,int dayOfMonth,String description) implements LedgerEvent {public RecurringRuleDefined{Objects.requireNonNull(eventId);Objects.requireNonNull(at);Objects.requireNonNull(category);Objects.requireNonNull(amount);if(dayOfMonth<1||dayOfMonth>28)throw new ValidationException("Recurring day must be 1..28");description=Objects.requireNonNullElse(description,"");}}
